import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Replay the migration contract baseline","description":"","frontmatter":{"docLocale":"en","counterpart":"/testing/contracts","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/testing/contracts.md","filePath":"en/testing/contracts.md"}'),n={name:"en/testing/contracts.md"};function r(o,e,d,c,l,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="replay-the-migration-contract-baseline" tabindex="-1">Replay the migration contract baseline <a class="header-anchor" href="#replay-the-migration-contract-baseline" aria-label="Permalink to &quot;Replay the migration contract baseline&quot;">​</a></h1><p>This guide is for developers who migrate the Lab Word service. M0 replays delivered Core, Foundation #2–#11, and #26–#28 behavior against real Rust HTTP/SSE. The new TypeScript service does not exist yet. Product behavior in #29–#40 is outside this baseline.</p><h2 id="get-the-first-result" tabindex="-1">Get the first result <a class="header-anchor" href="#get-the-first-result" aria-label="Permalink to &quot;Get the first result&quot;">​</a></h2><p>Run these commands at the repository root. Use the repository Node, pnpm, and Rust versions. Docker must be available.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core.test.ts</span></span></code></pre></div><p>The runner builds an isolated Rust target. It creates temporary PostgreSQL, Redis, RustFS, and Mailpit services. It applies migrations and starts the API and file cleanup Worker. It creates the first Owner through HTTP. Later registered test users are Members.</p><p>The terminal reports actual discovery and execution counts. <code>CORE-02</code> rejects a write without CSRF, checks the unchanged Lab list, then performs a valid write. <code>CORE-03</code> checks Agent access, invalid Bearer rejection without Cookie fallback, and revocation.</p><p>Without a file selection, <code>test:contract</code> runs the Core/API slice. Use <code>test:contract:all</code> for complete coverage.</p><p>Tests prepare business data through HTTP and observe results through HTTP/SSE. They return IDs and cursors unchanged. Process control provides real start, stop, and restart behavior.</p><h2 id="run-every-required-contract" tabindex="-1">Run every required contract <a class="header-anchor" href="#run-every-required-contract" aria-label="Permalink to &quot;Run every required contract&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract:all</span></span></code></pre></div><p>Each of the six profiles has separate data and an owned resource ledger. A failed profile fails the command.</p><table tabindex="0"><thead><tr><th>Profile</th><th>Checks</th><th>Explicit test configuration</th></tr></thead><tbody><tr><td><code>baseline</code></td><td>Identity, permissions, assets, world, devices, SSE, history, records, trends, and API contract</td><td>Production quotas and retention defaults</td></tr><tr><td><code>file-ttl</code></td><td>Signed upload/download expiration and authorization recovery</td><td>Download 2 seconds; upload session 5 seconds</td></tr><tr><td><code>session-ttl</code></td><td>Idle/absolute session expiry, SSE closure, and new login recovery</td><td>Idle 60 seconds; absolute 65 seconds</td></tr><tr><td><code>retention</code></td><td>Public cleanup, real gaps, unfinished tasks, last values, and expired Command receipts</td><td>Observations 2 seconds; ended records 3 seconds</td></tr><tr><td><code>rate</code></td><td>Primary quotas 20/60/600, 429, <code>Retry-After</code>, and window recovery</td><td>Window 5 seconds; unchanged primary quotas</td></tr><tr><td><code>capacity</code></td><td>1000 Entity/1000 Scene Node limits and rejected overflow</td><td>Rate limiting disabled for separate capacity checks</td></tr></tbody></table><p>Baseline uses five isolated batches: Core/API, assets/world, devices, history, and SSE. Their polls cannot exhaust one shared TCP client quota. The suite has six profiles and ten real runs.</p><p>Normal rate limits remain registration 20, authentication 60, and resource 600 per 60 seconds. The 5/20/120 <code>fallback_limit</code> values and 4096 buckets remain compatibility settings. They do not replace normal quotas. The former Redis outage mode is outside the shared new-service oracle.</p><p>During development, select a focused check against a compiled target:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sse.test.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retention</span></span></code></pre></div><p>Use <code>--no-build</code> only after compiling the current Rust source. It cannot prove that an older binary matches the candidate.</p><h2 id="read-coverage-and-failures" tabindex="-1">Read coverage and failures <a class="header-anchor" href="#read-coverage-and-failures" aria-label="Permalink to &quot;Read coverage and failures&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/tests/contract/behavior-matrix.json" target="_blank" rel="noreferrer">behavior matrix</a> records sources, normal results, unchanged rejected state, recovery, tests, and budgets. <code>public</code> uses HTTP/SSE. <code>configuration</code> uses existing configuration. <code>internal-supplement</code> assigns internal rules or use-case checks to later tickets. <code>gap</code> means required coverage remains missing. A gap prevents M0 completion.</p><p>Current public interfaces cannot reliably produce deterministic 24-hour spikes, bad quality, old sources, duplicate sequence values, exact SQL counts, or exactly eight pending SSE events. The matrix assigns those checks to #48/#50. Existing SQL/Runtime fixtures do not prove HTTP coverage. Shared contracts still verify real event bytes, reconnects, and credential revocation.</p><p>Evidence is in <code>.scratch/vnext-m0/runs/&lt;run-id&gt;/</code>. <code>results.json</code> records discovered, passed, and failed tests. <code>owned-resources.json</code> records acquisition intent, identities, consumers, and before/after inventories. <code>.scratch/vnext-m0/current.json</code> points to the latest run. The complete command also writes a suite manifest.</p><p>Classify a failure first. Compilation, zero discovery, and fixture failures are not business red evidence. Preserve the original assertion and budget for business failures. Fixture repairs cannot change production defaults. The Rust 24-hour capacity case uses 172800 seconds of observation retention only in that case. A separate HTTP case uses the default 86400 seconds to check cropping and retention gaps. Production defaults remain unchanged.</p><h2 id="compare-the-retained-api" tabindex="-1">Compare the retained API <a class="header-anchor" href="#compare-the-retained-api" aria-label="Permalink to &quot;Compare the retained API&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts:baseline:check</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/scripts/lib/contract-openapi.ts" target="_blank" rel="noreferrer">comparison tool</a> filters only removed knowledge, notification, email password-reset, generic jobs, and system cache routes. It preserves referenced DTOs and security declarations. Declaration order does not cause drift. DTO, operationId, response status, error, and security changes report JSON paths.</p><p>Run <code>node scripts/contract-api-baseline.mjs --input &lt;candidate-openapi.json&gt;</code> to compare another OpenAPI file. <code>--write</code> replaces the baseline. Use it only for an approved contract change. M0 does not fix schema version 28. Rust expectations come from current build and migration sources. Other targets report their actual versions.</p><h2 id="select-a-target-and-recover-resources" tabindex="-1">Select a target and recover resources <a class="header-anchor" href="#select-a-target-and-recover-resources" aria-label="Permalink to &quot;Select a target and recover resources&quot;">​</a></h2><p>Rust is the only built-in adapter. An executable descriptor can connect another target. This does not mean the new service exists:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/absolute/path/to/server&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [] }</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candidate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --descriptor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /absolute/path/to/target.json</span></span></code></pre></div><p>The target receives <code>APP_BIND</code>, <code>APP_ORIGIN</code>, and a separate <code>CONTRACT_DATA_DIRECTORY</code>. It must initialize that directory and serve the same HTTP contract. Non-Rust targets do not create Docker services. Optional <code>version</code> and <code>schemaVersion</code> fields verify target metadata.</p><p>Success, failure, timeout, SIGINT, and SIGTERM stop owned consumers and clean resources. After abnormal termination, wait for the original supervisor to stop. Then run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recover</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/vnext-m0/runs/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">run-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/owned-resources.json</span></span></code></pre></div><p>Recovery verifies process IDs, start tokens, PGID/session, and child process proofs. It then verifies container labels and immutable IDs. Unknown or replaced resources remain intact. Cleanup removes only proven resources in the owned ledger. It uses <code>docker rm -f -v</code> to remove anonymous volumes. It never runs global prune or removes existing root services and persistent volumes.</p><p>M0 Rust/Docker and process-group recovery validation covers Linux. Later foundation work owns Windows target adaptation and child-process checks. M0 does not claim a Windows pass.</p><p>Use <code>pnpm test:contract:lifecycle</code> for real interruption and wrapper descendant recovery checks. It creates its own isolated legacy stack. CI runs the complete contract on the final candidate. Local passes and a Draft PR do not replace final CI.</p><hr><p>Source version：<code>a455a4dba0f3</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/docs/testing/contracts.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,39)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
